(()=>{const zh=document.documentElement.lang.startsWith('zh'),keys=['ramp','fast','time'],el=Object.fromEntries(keys.map(k=>[k,document.getElementById('M05-'+k)]));let cur={};function response(t,r,fast){const u=Math.min(t,r),h=Math.max(t-r,0);return .4*u/r+.8*fast/r*(-Math.expm1(-u/fast))*Math.exp(-h/fast)+.6*40/r*(-Math.expm1(-u/40))*Math.exp(-h/40)}function draw(){const ramp=+el.ramp.value,fast=+el.fast.value,time=+el.time.value,stress=response(time,ramp,fast),peak=response(ramp,ramp,fast),strain=.02*Math.min(time/ramp,1);cur={ramp,fast,time,stress_kPa:stress,peak_kPa:peak,strain,hold:time>=ramp,equilibrium_kPa:.4};keys.forEach(k=>document.getElementById('M05-'+k+'-value').textContent=cur[k].toFixed(k==='time'?0:1));const X=t=>85+620*t/300,Y=s=>390-s/1.8*210,Z=s=>120-s/.02*65;let out='<rect width="800" height="460" fill="#f5f8f8"/>';for(let t=0;t<=300;t+=60){out+=`<line x1="${X(t)}" x2="${X(t)}" y1="35" y2="390" stroke="#dce5e7"/><text x="${X(t)}" y="415" text-anchor="middle">${t}</text>`}let ps='',pe='';for(let i=0;i<=900;i++){const t=i/3;ps+=(i?' L':'M')+X(t)+','+Y(response(t,ramp,fast));pe+=(i?' L':'M')+X(t)+','+Z(.02*Math.min(t/ramp,1))}for(let s=0;s<=1.8;s+=.6)out+=`<text x="70" y="${Y(s)+5}" text-anchor="end">${s.toFixed(1)}</text>`;out+=`<text x="70" y="${Z(.02)+5}" text-anchor="end">2%</text><text x="70" y="${Z(0)+5}" text-anchor="end">0</text><path d="${pe}" fill="none" stroke="#188777" stroke-width="3"/><path d="${ps}" fill="none" stroke="#186c94" stroke-width="3"/><line x1="85" x2="705" y1="${Y(.4)}" y2="${Y(.4)}" stroke="#81939e" stroke-dasharray="5 4"/><line x1="${X(time)}" x2="${X(time)}" y1="35" y2="390" stroke="#d27839"/><circle cx="${X(time)}" cy="${Y(stress)}" r="6" fill="#d27839"/><text x="90" y="25">${zh?'上：实际应变；下：应力':'Top: actual strain; bottom: stress'}</text><text transform="translate(22 280) rotate(-90)" text-anchor="middle">${zh?'应力 / kPa':'Stress / kPa'}</text><text x="400" y="450" text-anchor="middle">${zh?'从加载开始的时间 / s':'Time from ramp start / s'}</text>`;document.getElementById('M05-plot').innerHTML=out;document.getElementById('M05-values').textContent=(cur.hold?(zh?'保持阶段':'Holding'):(zh?'加载阶段':'Loading'))+' · ε='+(strain*100).toFixed(3)+'% · σ='+stress.toFixed(5)+' kPa · '+(zh?'峰值':'Peak')+' '+peak.toFixed(5)+' kPa';return {...cur}}function set(p){keys.forEach(k=>{if(k in p)el[k].value=p[k]});return draw()}function reset(){return set({ramp:1,fast:2,time:20})}keys.forEach(k=>el[k].addEventListener('input',draw));document.getElementById('M05-reset').addEventListener('click',reset);window.CourseLab={set,state:()=>({...cur}),reset,destroy(){}};reset()})();